  /// < Out of memory
  static const int VPNSVC_ERROR_OUT_OF_MEMORY = -12;

  /// < Permission denied
  static const int VPNSVC_ERROR_PERMISSION_DENIED = -13;

  /// < No such file or directory
  static const int VPNSVC_ERROR_NO_SUCH_FILE = -2;

  /// < IO error
  static const int VPNSVC_ERROR_IO_ERROR = -5;

  /// < Time out error or no answer
  static const int VPNSVC_ERROR_TIMEOUT = -1073741823;

  /// < Failed to communicate with server
  static const int VPNSVC_ERROR_IPC_FAILED = -30081022;

  /// < Not Supported
  static const int VPNSVC_ERROR_NOT_SUPPORTED = -1073741822;
}

